const e=[{name:"Build",desc:"Custom software and AI, from a two-week prototype to production.",keys:["ai","web","mobile","desktop"]},{name:"Automate & connect",desc:"Busywork handed to software, and numbers you can trust.",keys:["automation","data"]},{name:"Run & rescue",desc:"Infrastructure that stays up, and projects put back on track.",keys:["cloud","rescue"]}],t={"ai-machine-learning":{intro:"We build AI that does one specific job inside your business: an assistant that answers from your own documents, an agent that reads an email and updates your CRM, a model that transcribes calls or checks photos. Every feature is tested on real examples from your work before it ships, and it hands off to a person when it isn't sure.",outcomes:["AI that answers from your own data, with sources people can check","Clear rules for when the AI acts on its own and when a person approves","Quality measured on real examples before launch and on every release","Running costs understood and planned before you commit"],included:[{title:"Build",items:["LLM assistants and agents","Retrieval over your documents (RAG)","Vision, speech and document models"]},{title:"Safeguards",items:["Permissions that follow your existing roles","Human review and hand-off rules","Guardrails and safe fallbacks"]},{title:"Quality",items:["Evaluation set built from your real cases","Cost and response-time monitoring","Model and prompt documentation"]}],steps:[{title:"Free call",desc:"We talk through the task and the data behind it, and tell you honestly whether AI is the right tool."},{title:"Two-week prototype",desc:"The core AI working on a sample of your real data, so you can judge the answers for yourself."},{title:"Build",desc:"Production engineering with a demo every week and evaluations on every change."},{title:"Launch & measure",desc:"A staged rollout, with quality, cost and hand-offs monitored from day one."}],roles:[{role:"AI engineer",does:"Designs the prompts, retrieval, agents and evaluation set."},{role:"Full-stack engineer",does:"Builds the app, APIs and integrations around the AI."},{role:"Data engineer",does:"Prepares, indexes and syncs the data the AI draws on."},{role:"Your subject expert",does:"From your side: judges the answers and sets the rules the AI must follow."}],stack:["AI models","AI frameworks","Data & integration","Cloud & DevOps"],solutions:["Knowledge Assistant","Document AI","AI Voice Agent"],related:["business-process-automation","data-engineering-analytics","custom-software-development"],faqs:[{q:"Which AI model will you use?",a:"Whichever does the job best for your task, data and budget. We compare models on your own examples during the prototype, and design the system so the model can be swapped later."},{q:"Is our data used to train public models?",a:"No. We use providers and settings that don't train on your data, and where data must stay in-house we can run open models in your own cloud account."},{q:"What happens when the AI gets something wrong?",a:"We design for it. Low-confidence answers go to a person, every action is logged, and mistakes are added to the evaluation set so they don't come back."},{q:"Can you add AI to software we already have?",a:"Yes. Many projects add an assistant or an automation to an existing product or internal tool through its API or database, without rebuilding it."}]},"custom-software-development":{intro:"Off-the-shelf tools get you most of the way. The last part is often where your team's week goes: spreadsheets, re-typing and workarounds between systems. We build web applications, customer portals and SaaS products around how your business actually runs, and connect them to the tools you already use.",outcomes:["Software that fits your workflow, not the other way around","One place for work that's spread across spreadsheets and inboxes today","Clean code and documentation your own engineers can pick up","Integrations that keep your existing systems in step"],included:[{title:"Product",items:["Workflow map and success measures","Working prototype on your own data","Interface design and a reusable component library"]},{title:"Engineering",items:["Web apps, portals and admin back offices","APIs and integrations","Sign-in, roles and audit trails"]},{title:"Handover",items:["Source code in your repository","Automated tests and CI/CD","Runbooks and architecture notes"]}],steps:[{title:"Free call",desc:"Walk us through the workflow and the tools it touches today."},{title:"Two-week prototype",desc:"The core screens working on your own data, for your team to try on real tasks."},{title:"Build",desc:"A fixed-scope build in short iterations, with a working demo every week."},{title:"Launch & hand over",desc:"A staged release, training for your team, and everything handed over in your name."}],roles:[{role:"Tech lead",does:"Owns the architecture, security and code quality."},{role:"Full-stack engineer",does:"Builds the front end, APIs and integrations."},{role:"Product designer",does:"Shapes the screens and tests them with the people who'll use them."},{role:"Your product owner",does:"From your side: sets priorities and signs off each milestone."}],stack:["Web & backend","Data & integration","Cloud & DevOps"],solutions:["Client Portal","Field Operations App","Reporting Autopilot"],related:["mobile-app-development","ai-machine-learning","cloud-devops"],faqs:[{q:"Should we build custom software or buy a product?",a:"Buy when a product fits, and we'll tell you so on the first call. Custom software makes sense when the work is specific to how you operate, or when your team is stitching several tools together by hand."},{q:"Can you build a SaaS product from scratch?",a:"Yes. We build MVPs and full products, including customer accounts, billing with Stripe, admin tools and the analytics that show how early users actually use it."},{q:"Who owns the code?",a:"You do, from the first commit. It lives in your repository and runs in your own cloud accounts."},{q:"Can you work with our existing developers?",a:"Yes. We can lead the build, or join your team, follow your conventions and review code together."}]},"mobile-app-development":{intro:"Some work happens away from a desk: on a job site, in a warehouse, at a customer's door. We build iOS and Android apps for field teams and for your customers, designed for poor signal, gloves, glare and hurried moments, and connected to the office systems behind them.",outcomes:["Field data captured once, at the source, instead of re-typed later","Apps that keep working offline and sync when signal returns","Customers who can serve themselves from their phone","One codebase for iOS and Android where that suits the app"],included:[{title:"App",items:["iOS and Android apps","Offline storage and sync","Camera, GPS, barcode scanning and signatures"]},{title:"Backend",items:["APIs and an office dashboard","Push notifications","Integrations with your office systems"]},{title:"Release",items:["App Store and Google Play submission","Private distribution for staff apps","Crash reporting and usage analytics"]}],steps:[{title:"Free call",desc:"Tell us who uses the app, where they are, and how the work gets done today."},{title:"Two-week prototype",desc:"A working app on real phones with your data, for a few people to try in the field."},{title:"Build",desc:"Weekly test builds your team installs and uses, with their feedback shaping the next one."},{title:"Launch",desc:"Store submission or private release, a staged rollout and short training sessions."}],roles:[{role:"Mobile engineer",does:"Builds the app, offline sync and device features."},{role:"Backend engineer",does:"Builds the APIs, dashboard and integrations behind it."},{role:"Product designer",does:"Designs for small screens, gloves and bright sunlight."},{role:"QA engineer",does:"Tests on real devices and on poor connections."}],stack:["Mobile & desktop","Web & backend","Cloud & DevOps"],solutions:["Field Operations App","Client Portal"],related:["custom-software-development","ai-machine-learning","cloud-devops"],faqs:[{q:"Native or cross-platform?",a:"Usually cross-platform with React Native or Flutter, which keeps one codebase for both stores. We go native with Swift or Kotlin when the app needs deep hardware access or the best possible performance."},{q:"Does it work without signal?",a:"If it needs to, yes. We design offline-first: data is saved on the device and syncs safely when the connection returns, with clear rules for when two people edit the same record."},{q:"Can the app be private to our staff?",a:"Yes. Staff apps can be distributed privately through Apple Business Manager, managed Google Play or your device-management tool, without appearing in the public stores."},{q:"Who publishes it to the app stores?",a:"We handle submission and review under your own developer accounts, so the app and its listing stay yours."}]},"desktop-software":{intro:"The browser isn't always the right home for software. When the work involves large files, local hardware, Office documents or data that must stay on the machine, we build Windows, macOS and Linux applications and Microsoft Office add-ins that fit the way people already work.",outcomes:["Tools that handle large files and local hardware without strain","Automation inside Excel, Word and Outlook, where the work already happens","Data that stays on the machine or the local network when it must","Installs and updates that don't need IT to babysit them"],included:[{title:"Applications",items:["Windows, macOS and Linux apps","Microsoft Office add-ins","Connections to scanners, printers and local devices"]},{title:"Delivery",items:["Signed installers and automatic updates","Central settings and licensing","Crash reporting and logs"]}],steps:[{title:"Free call",desc:"Show us the task, the files and the machines it runs on."},{title:"Two-week prototype",desc:"A working build on your own files and hardware, for a few people to try."},{title:"Build",desc:"Weekly builds installed on real machines, with automated tests on every change."},{title:"Roll out",desc:"Signed installers, a staged rollout through your IT tools, and training for users and support staff."}],roles:[{role:"Desktop engineer",does:"Builds the application in .NET, Electron or native code."},{role:"Automation engineer",does:"Builds Office add-ins and the links to your other systems."},{role:"QA engineer",does:"Tests on the operating systems and hardware you actually use."}],stack:["Mobile & desktop","Web & backend","Data & integration"],solutions:["Document AI","Reporting Autopilot"],related:["business-process-automation","project-rescue-modernization","custom-software-development"],faqs:[{q:"Why desktop instead of a web app?",a:"Desktop makes sense for heavy files, local hardware such as scanners or instruments, offline work, or data that must not leave the machine. If a web app would do the job, we'll recommend that instead."},{q:"Can you build add-ins for Excel, Word or Outlook?",a:"Yes. Office add-ins are a practical way to automate work in the spreadsheets, documents and inboxes your team already lives in."},{q:"How are updates delivered?",a:"Through signed installers that update themselves, or through your IT team's deployment tools such as Microsoft Intune, so nobody installs new versions by hand."},{q:"Can you update an old desktop application?",a:"Yes. We can stabilize and modernize an existing Windows application, often a piece at a time, so people keep working throughout."}]},"business-process-automation":{intro:"Most teams have a task that eats hours every week: copying data between systems, chasing approvals, re-typing documents, building the same report again. We hand that work to software. Documents get read, systems stay in sync and people get nudged, with a person approving the steps that matter.",outcomes:["Re-typing and copy-paste handed to software","Systems that agree with each other without manual exports","Approvals and follow-ups that happen on time","A clear log of what ran, what was flagged and who approved it"],included:[{title:"Workflows",items:["Workflow map and automation design","Approval and exception queues","Email, Slack and Microsoft Teams notifications"]},{title:"Documents",items:["Document reading and data extraction","Checks against your rules and records","Human review for anything unusual"]},{title:"Integrations",items:["Connectors to accounting, CRM and ERP systems","Scheduled and event-driven syncs","Monitoring and error alerts"]}],steps:[{title:"Free call",desc:"Tell us the task that eats your week and the systems it touches."},{title:"Two-week prototype",desc:"One real workflow automated end to end on your own data, running alongside the manual process."},{title:"Build",desc:"More workflows, edge cases and approvals, shipped in weekly increments."},{title:"Switch over",desc:"Move across in stages, watch every run and tune the rules with your team."}],roles:[{role:"Automation engineer",does:"Designs and builds the workflows, queues and alerts."},{role:"AI engineer",does:"Handles document reading and the judgment calls inside the workflow."},{role:"Integration engineer",does:"Connects your accounting, CRM and operations systems."},{role:"Your process owner",does:"From your side: knows the edge cases and approves the rules."}],stack:["AI models","Data & integration","Web & backend","Cloud & DevOps"],solutions:["Document AI","Reporting Autopilot","AI Voice Agent"],related:["ai-machine-learning","data-engineering-analytics","custom-software-development"],faqs:[{q:"Do we need to replace our current systems?",a:"No. Automation works with the systems you already have, through their APIs or exports, and where nothing else exists, through carefully built screen automation."},{q:"What if a document or case doesn't fit the rules?",a:"It goes to a review queue for a person, with the reason it was flagged. Nothing unusual is posted without someone checking it."},{q:"Why not just use Zapier or n8n ourselves?",a:"For simple, low-risk flows, you should, and we use tools like n8n too. We're useful when a workflow needs document reading, careful error handling, approvals or systems those tools don't reach."},{q:"How do we know it's working?",a:"Every run is logged, failures raise an alert, and a simple dashboard shows what was processed, what was flagged and what needed a person."}]},"cloud-devops":{intro:"Software is only as dependable as the platform it runs on. We set up infrastructure in your own AWS, Azure or Google Cloud account, defined as code, with automated deployments, monitoring and backups, so releases are routine and the monthly bill makes sense.",outcomes:["Infrastructure in your own cloud account, defined as code","Releases that are routine, tested and easy to roll back","Problems caught by monitoring before customers notice them","A cloud bill you understand, with costs tracked over time"],included:[{title:"Foundations",items:["Cloud accounts, networking and access","Infrastructure as code (Terraform)","Backups and a disaster-recovery plan"]},{title:"Delivery",items:["CI/CD pipelines","Staging and production environments","Secrets and configuration management"]},{title:"Operations",items:["Monitoring, logging and alerts","Cost dashboards and budgets","Runbooks and on-call guidance"]}],steps:[{title:"Free call",desc:"Tell us what runs today, where it runs, and what worries you about it."},{title:"Assess",desc:"Review the current setup, costs and risks, and agree a prioritized plan."},{title:"Build",desc:"Infrastructure as code, pipelines and monitoring, rolled out one environment at a time."},{title:"Hand over & support",desc:"Runbooks and training for your team, with ongoing support if you want it."}],roles:[{role:"Cloud & DevOps engineer",does:"Builds the infrastructure, pipelines and monitoring."},{role:"Tech lead",does:"Owns the architecture, security and cost decisions."},{role:"Your IT or engineering lead",does:"From your side: agrees access, policies and who is on call."}],stack:["Cloud & DevOps","Data & integration","Web & backend"],solutions:["Client Portal","Knowledge Assistant","Reporting Autopilot"],related:["project-rescue-modernization","custom-software-development","data-engineering-analytics"],faqs:[{q:"Do you host our software?",a:"No, and that's deliberate. Everything runs in cloud accounts you own, so you keep control of access, data and billing. We can look after it for you under a support plan."},{q:"Which cloud should we use?",a:"Usually the one you already have, or the one your other systems and your team know best. AWS, Azure and Google Cloud are all sound choices; the right one depends on your tools and your compliance needs."},{q:"Can you lower our cloud costs?",a:"Often. A review usually turns up oversized servers, idle resources or missing budgets. We show you what we found and what each change involves before touching anything."},{q:"Can you set up infrastructure for healthcare data?",a:"Yes. We build infrastructure to support HIPAA requirements, with encryption, access controls, audit logs and cloud services covered by a business associate agreement, and we document the setup for your own compliance review."}]},"data-engineering-analytics":{intro:"The numbers you need usually exist already, spread across accounting, CRM, project tools and a stack of spreadsheets. Someone spends hours each week stitching them together. We join those sources into one checked database in your own cloud, then build the dashboards, reports and alerts on top, so the numbers update themselves.",outcomes:["One trustworthy source of truth instead of competing spreadsheets","Dashboards and reports that update without anyone rebuilding them","Agreed definitions, so every team means the same thing by each number","Alerts when a number moves out of range, not weeks later"],included:[{title:"Foundation",items:["Source map and data dictionary","Pipelines from your business systems","Warehouse models with tests on every load"]},{title:"Insight",items:["Dashboards for owners, managers and teams","Scheduled reports and AI-written summaries","Alerts by email, Slack or Microsoft Teams"]}],steps:[{title:"Free call",desc:"Tell us which numbers you need, who needs them and where they live today."},{title:"Two-week prototype",desc:"Two or three of your sources joined into a first working dashboard on your own data."},{title:"Build",desc:"More sources, tested models and the reports each team uses, delivered week by week."},{title:"Launch & hand over",desc:"Training for the people who read and maintain it, plus a data dictionary everyone can use."}],roles:[{role:"Data engineer",does:"Builds the pipelines and the warehouse."},{role:"Analytics engineer",does:"Models the data and agrees the definitions with your team."},{role:"Analyst",does:"Designs dashboards around the decisions people actually make."},{role:"Your data owner",does:"From your side: knows the sources and signs off the definitions."}],stack:["Data & integration","Web & backend","AI models","Cloud & DevOps"],solutions:["Reporting Autopilot","Document AI"],related:["business-process-automation","ai-machine-learning","cloud-devops"],faqs:[{q:"Do we need a data warehouse already?",a:"No. We can set up a lightweight warehouse in your own cloud as part of the project, or build on the one you have."},{q:"Which dashboard tool will we use?",a:"Whichever suits your team: Power BI, Looker Studio, Metabase or dashboards built into your own app. If you already pay for one, we'll usually build on it."},{q:"Who owns the data?",a:"You do. The pipelines and the warehouse run in your accounts, and every source and definition is documented."},{q:"Can we start small?",a:"Yes. Most projects start with one question that matters and the two or three sources behind it, then grow from there."}]},"project-rescue-modernization":{intro:"Sometimes a build stalls: the previous vendor has gone quiet, deadlines keep slipping, or the system that runs the business is too fragile to change. We audit the code and the infrastructure, stabilize what's breaking, and move the project forward in small, safe steps, without betting everything on a rewrite.",outcomes:["An honest, written picture of where the project really stands","The urgent problems fixed first, so the business stops firefighting","A plan to finish or modernize in steps, each one shippable","Code, accounts and know-how back under your control"],included:[{title:"Audit",items:["Code, architecture and security review","Infrastructure and access review","Written findings with a prioritized plan"]},{title:"Stabilize",items:["Fixes for the most urgent bugs and outages","Automated tests around critical paths","Monitoring, backups and a deployment pipeline"]},{title:"Move forward",items:["Stalled features finished","Legacy parts modernized piece by piece","Documentation and handover to your team"]}],steps:[{title:"Free call",desc:"Tell us what's stuck and what the business needs from the system next."},{title:"Audit",desc:"Read the code, check the infrastructure, recover access and write down what we find."},{title:"Stabilize",desc:"Fix the urgent problems, then add tests and monitoring so changes stop breaking things."},{title:"Modernize & hand over",desc:"Finish or replace parts in small releases, and leave your team able to run it."}],roles:[{role:"Tech lead",does:"Leads the audit and owns the recovery plan."},{role:"Senior engineer",does:"Fixes, tests and modernizes the code."},{role:"Cloud & DevOps engineer",does:"Secures access, pipelines, monitoring and backups."}],stack:["Web & backend","Mobile & desktop","Data & integration","Cloud & DevOps"],solutions:[],related:["cloud-devops","custom-software-development","desktop-software"],faqs:[{q:"Do you always recommend a rewrite?",a:"Rarely. Rewrites are slow and risky. Most systems can be stabilized and modernized a piece at a time while the business keeps using them."},{q:"We've lost access to our code or hosting. Can you help?",a:"Often, yes. We work with you, your previous vendor and the hosting providers to recover repositories, domains and cloud accounts, and put them in your name."},{q:"What do we get from the audit?",a:"A plain-language written report: what works, what's risky, what it would take to fix, and a recommended order of work, so you can decide with or without us."},{q:"Can you take over a project another company started?",a:"Yes. Most rescues are exactly that. We read what's there and understand it before we change anything."}]}};export{t as a,e as s};
